style.css:
@-moz-document domain("docs.google.com") {
/* Base background */
    body, .docs-grille-gm3 {
        background-color: #0f1117 !important;
        color: #e6edf3 !important;
    }

    /* Top bar */
    .docs-titlebar, .docs-menubar, .docs-toolbar {
        background-color: #161b22 !important;
        border-color: #30363d !important;
    }

    /* Grid area */
    .grid-container, .grid-table-container {
        background-color: #0d1117 !important;
    }

    /* Cells */
    .grid-cell {
        background-color: #0d1117 !important;
        color: #e6edf3 !important;
        border-color: #30363d !important;
    }

    /* Selected cell */
    .grid-cell.focused {
        background-color: #1f6feb !important;
        color: #ffffff !important;
    }

    /* Column and row headers */
    .column-headers-background,
    .row-headers-background {
        background-color: #161b22 !important;
        color: #c9d1d9 !important;
        border-color: #30363d !important;
    }

    /* Sheet tabs */
    .docs-sheet-tab {
        background-color: #161b22 !important;
        color: #c9d1d9 !important;
    }

    .docs-sheet-tab.docs-sheet-active-tab {
        background-color: #21262d !important;
        color: #ffffff !important;
    }

    /* Sidebar / panels */
    .docs-sidebar, .docs-material {
        background-color: #161b22 !important;
        color: #e6edf3 !important;
    }

    /* Input fields */
    input, textarea {
        background-color: #0d1117 !important;
        color: #e6edf3 !important;
        border: 1px solid #30363d !important;
    }

    /* Scrollbars (webkit browsers) */
    ::-webkit-scrollbar {
        width: 10px;
        height: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #0d1117;
    }

    ::-webkit-scrollbar-thumb {
        background: #30363d;
        border-radius: 6px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #484f58;
    }

    /* Buttons */
    button {
        background-color: #21262d !important;
        color: #e6edf3 !important;
        border: 1px solid #30363d !important;
    }

    button:hover {
        background-color: #30363d !important;
    }
}
